function cleanText(value) {
    if (value == null) return '';

    return String(value)
        .replace(/\r\n?/g, '\n')
        .replace(/\n[ \t]*\n[ \t]*\n+/g, '\n\n')
        .split('\n')
        .map(line => line.replace(/[ \t]+$/g, ''))
        .join('\n')
        .trim();
}

function chunkText(text, maxChars = 1400, overlapChars = 160) {
    text = cleanText(text);
    if (!text) return [];
    if (text.length <= maxChars) return [text];

    const lines = text.split('\n');
    const chunks = [];
    let current = [];
    let currentLength = 0;

    function pushCurrent() {
        const value = current.join('\n').trim();
        if (value) chunks.push(value);
    }

    function makeOverlap(linesArray) {
        let total = 0;
        const out = [];

        for (let i = linesArray.length - 1; i >= 0; i--) {
            const lineLength = linesArray[i].length + 1;
            if (out.length > 0 && total + lineLength > overlapChars) break;
            out.unshift(linesArray[i]);
            total += lineLength;
            if (total >= overlapChars) break;
        }

        return out;
    }

    for (const line of lines) {        
        if (line.length > maxChars) {
            if (current.length) {
                pushCurrent();
                current = makeOverlap(current);
                currentLength = current.join('\n').length;
            }

            let start = 0;
            while (start < line.length) {
                const piece = line.slice(start, start + maxChars).trim();
                if (piece) chunks.push(piece);
                start += maxChars - Math.min(overlapChars, 200);
            }

            current = [];
            currentLength = 0;
            continue;
        }

        const addedLength = line.length + (current.length ? 1 : 0);

        if (current.length && currentLength + addedLength > maxChars) {
            pushCurrent();
            current = makeOverlap(current);
            currentLength = current.join('\n').length;

            if (currentLength + 1 + line.length > maxChars) {
                current = [line];
                currentLength = line.length;
                continue;
            }
        }

        current.push(line);
        currentLength += addedLength;
    }

    pushCurrent();
    return chunks;
}

function hash32(str, seed) {
    let h = seed >>> 0;

    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 16777619) >>> 0;
    }

    return h >>> 0;
}

function stableUuid(key) {
    const seeds = [
        2166136261,
        0x9e3779b9,
        0x85ebca6b,
        0xc2b2ae35,
    ];

    const parts = seeds.map(seed => {
        return hash32(key, (2166136261 ^ seed) >>> 0)
            .toString(16)
            .padStart(8, '0');
    });

    const h = parts.join('');

    return `${h.slice(0, 8)}-${h.slice(8, 12)}-5${h.slice(13, 16)}-8${h.slice(17, 20)}-${h.slice(20)}`;
}

const issue = $input.first().json;
const chunks = [];

const baseContext = [
    `Jira Issue ID: ${issue.issue_id}`,
    issue.summary ? `Summary: ${issue.summary}` : '',
].filter(Boolean).join('\n');

function addChunk(type, text, extra = {}) {
    text = cleanText(text);
    if (!text) return;

    const partIndex = extra.part_index ?? extra.comment_chunk_index ?? extra.attachment_chunk_index ?? 0;
    const sourceKey = extra.attachment_id ?? extra.comment_index ?? '';

    const pointId = stableUuid(
        `${issue.issue_id}|${type}|${sourceKey}|${partIndex}|${text}`
    );

    const payload = {
        issue_id: issue.issue_id,
        ...(issue.summary ? {
            summary: issue.summary
        } : {}),
        votes: issue.votes,
        source: issue.source,
        document_type: issue.document_type,
        schema_version: issue.schema_version,
        chunk_type: type,
        embedding_model: 'nomic-embed-text',
        embedding_task: 'search_document',
        ...extra,
        text,
    };

    chunks.push({
        point_id: pointId,
        text,
        chunk_type: type,
        payload,
    });
}

addChunk(
    'overview',
    [
        baseContext
    ].filter(Boolean).join('\n')
);

// 2. Description.
for (const [index, part] of chunkText(issue.description).entries()) {
    addChunk(
        'description',
        `${baseContext}\n\nDescription:\n${part}`, {
            part_index: index
        }
    );
}

for (const attachment of issue.attachments || []) {
    const attachmentHeader = [
        baseContext,
        `Attachment ID: ${attachment.attachment_id}`,
        attachment.name ? `Attachment Name: ${attachment.name}` : '',
        attachment.type ? `Attachment Type: ${attachment.type}` : '',
        attachment.mime_type ? `MIME Type: ${attachment.mime_type}` : '',
        attachment.extractor ? `Extraction Method: ${attachment.extractor}` : '',
        '',
        'Attachment Content:',
    ].filter(Boolean).join('\n');

    const parts = chunkText(attachment.content);

    for (const [index, part] of parts.entries()) {
        addChunk(
            'attachment',
            `${attachmentHeader}\n${part}`, {
                attachment_id: attachment.attachment_id,
                attachment_name: attachment.name || '',
                attachment_type: attachment.type || 'Unknown',
                attachment_mime_type: attachment.mime_type || '',
                attachment_extractor: attachment.extractor || 'unknown',
                attachment_chunk_index: index,
            }
        );
    }
}

for (const comment of issue.comments || []) {
    const commentHeader = [
        baseContext,
        `Comment ${comment.index}:`,
        '',
    ].filter(Boolean).join('\n');

    const parts = chunkText(comment.text);

    for (const [index, part] of parts.entries()) {
        addChunk(
            'comment',
            `${commentHeader}${part}`, {
                comment_index: comment.index,
                comment_chunk_index: index,
            }
        );
    }
}

const total = chunks.length;

for (let i = 0; i < chunks.length; i++) {
    chunks[i].payload.chunk_index = i;
    chunks[i].payload.chunk_total = total;
    chunks[i].payload.chunk_id = chunks[i].point_id;
}

return chunks.map(chunk => ({
    json: chunk,
}));
